      if (!store) return 0;
      let count = 0;
      for (const [id, record] of store.entries()) {
        if (matchesInternalWhere(record, where)) {
          store.set(id, { ...record, ...data });
          count++;
        }
      }
      return count;
    },

    async delete(
      table: string,
      where: Array<{ field: string; op: string; value: unknown }>,
    ): Promise<number> {
      const store = internalStore.get(table);
      if (!store) return 0;
      let count = 0;
      for (const [id, record] of store.entries()) {
        if (matchesInternalWhere(record, where)) {
          store.delete(id);
          count++;
        }
      }
